script:
(function () {
  'use strict';
  // Equipment buy vs lease: after-tax net present cost of each option over the lease term N (months).
  // Cash flows are discounted monthly at d / 12 (d = discount rate; default = loan rate x (1 - tax rate)).
  // BUY: cost basis B = price x (1 + sales tax) + upfront fees. Loan L = price x (1 + sales tax) - down,
  //   level payment P = L r / (1 - (1 + r)^-n), r = loan rate / 12 (L / n at 0%).
  //   Month 0: -(down + fees). Months 1..min(N, n): -P.
  //   Tax saved at the end of each tax year (month 12y, or N for a short last year):
  //     tax rate x (interest paid that year + depreciation that year).
  //     Straight-line: B / life per year (pro rata for a partial last year), never below zero book value.
  //     Fixed rate: rate x remaining book value per year (pro rata for a partial year).
  //   Month N: + resale value (price x residual %) - loan balance still owed
  //            - tax rate x (resale value - remaining book value)   (a loss gives a tax saving).
  // LEASE: month 0: -(deposit + fees), plus the first payment when paid in advance; payments at months
  //   0..N-1 (in advance) or 1..N (in arrears). Tax saved at each year end: tax rate x (payments in that
  //   year + fees in year 1). Month N: + deposit back.
  // Net cost = -(present value of the cash flows); the option with the lower net cost is better.
  // Verified (scratchpad b4biz/eb.test.js):
  //   identity: tax 0, discount = loan rate, no fees, loan term = lease term, 0% resale -> net cost of
  //   buying = price x (1 + sales tax) exactly (the loan's PV at its own rate equals the amount borrowed);
  //   lease in arrears with tax 0: $1,000 x 36 at 6% / 12 = $32,871.02 (annuity table factor 32.87102);
  //   in advance = arrears x 1.005; a deposit of D costs D (1 - 1.005^-36);
  //   payment check: $48,500 at 8% for 60 months -> $983.41 (standard amortization value);
  //   straight-line 5 years on $54,000 with no discounting -> 3 years of tax-deductible depreciation
  //   $32,400; with a 40% resale value the taxable gain is $20,000 - $21,600 = -$1,600 (a loss);
  //   100% rate deducts the whole basis in year 1 ($54,000 x 25% = $13,500 saved in year 1);
  //   default example (hand-checked year by year): buy $29,815 vs lease $26,657 net cost.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var money2 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });

  function fmt(x) { return Math.abs(x) < 0.5 ? money.format(0) : money.format(x); }
  function signed(x) { return Math.abs(x) < 0.5 ? money.format(0) : (x > 0 ? '+' : '−') + money.format(Math.abs(x)); }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function num(id) { var v = parseFloat(document.getElementById(id).value); return isNaN(v) ? NaN : v; }

  function levelPayment(L, annual, n) {
    if (L <= 0) return 0;
    var r = annual / 12;
    return r === 0 ? L / n : L * r / (1 - Math.pow(1 + r, -n));
  }

  // p: price, salesTax, down, buyFees, loanRate, loanTerm, method, life, depRate, residual,
  //    leasePay, leaseTerm, deposit, leaseFees, advance, tax, disc (all rates as decimals)
  function analyse(p) {
    var N = p.leaseTerm, i = p.disc / 12, years = Math.ceil(N / 12);
    var cost = p.price * (1 + p.salesTax), basis = cost + p.buyFees;
    var L = Math.max(0, cost - p.down), n = p.loanTerm, P = levelPayment(L, p.loanRate, n), r = p.loanRate / 12;
    var buyFlows = [], leaseFlows = [];   // [month, amount, kind, year]
    var yr = [];
    for (var y = 0; y <= years; y++) yr.push({ bPay: 0, bTax: 0, bEnd: 0, lPay: 0, lTax: 0, lEnd: 0 });
    function flow(list, month, amount, year, key) { list.push([month, amount]); yr[year][key] += amount; }

    // Buy
    flow(buyFlows, 0, -(p.down + p.buyFees), 0, 'bPay');
    var bal = L, book = basis, totalBuyTax = 0;
    for (y = 1; y <= years; y++) {
      var first = 12 * (y - 1) + 1, last = Math.min(12 * y, N), monthsIn = last - first + 1, interest = 0;
      for (var m = first; m <= last; m++) {
        if (m <= n && bal > 0) {
          var int = bal * r;
          interest += int;
          bal = Math.max(0, bal + int - P);
          flow(buyFlows, m, -P, y, 'bPay');
        }
      }
      var dep = p.method === 'sl' ? basis / p.life * monthsIn / 12 : book * p.depRate * monthsIn / 12;
      dep = Math.min(dep, book);
      book -= dep;
      var saved = p.tax * (interest + dep);
      totalBuyTax += saved;
      flow(buyFlows, last, saved, y, 'bTax');
    }
    var resale = p.price * p.residual;
    var gainTax = p.tax * (resale - book);
    var endBuy = resale - bal - gainTax;
    flow(buyFlows, N, endBuy, years, 'bEnd');

    // Lease
    flow(leaseFlows, 0, -(p.deposit + p.leaseFees), 0, 'lPay');
    var taxByYear = [];
    for (y = 0; y <= years; y++) taxByYear.push(0);
    taxByYear[1] += p.leaseFees;
    for (var k = 0; k < N; k++) {
      var month = p.advance ? k : k + 1;
      var payYear = p.advance ? Math.floor(k / 12) + 1 : Math.ceil((k + 1) / 12);
      flow(leaseFlows, month, -p.leasePay, month === 0 ? 0 : payYear, 'lPay');
      taxByYear[payYear] += p.leasePay;
    }
    var totalLeaseTax = 0;
    for (y = 1; y <= years; y++) {
      var s = p.tax * taxByYear[y];
      totalLeaseTax += s;
      flow(leaseFlows, Math.min(12 * y, N), s, y, 'lTax');
    }
    flow(leaseFlows, N, p.deposit, years, 'lEnd');

    function pv(list) { return list.reduce(function (sum, f) { return sum + f[1] / Math.pow(1 + i, f[0]); }, 0); }
    return {
      buyCost: -pv(buyFlows), leaseCost: -pv(leaseFlows), payment: P, loan: L, loanLeft: bal, book: book,
      resale: resale, gainTax: gainTax, buyTax: totalBuyTax, leaseTax: totalLeaseTax, years: yr
    };
  }

  function clearBody(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }

  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) { var td = document.createElement('td'); td.textContent = text; tr.appendChild(td); });
    body.appendChild(tr);
  }

  function clearResults() {
    ['ebBest', 'ebBuyNpv', 'ebLeaseNpv', 'ebLoanPay', 'ebLoanAmt', 'ebLoanLeft', 'ebBuyTax', 'ebLeaseTax', 'ebRateUsed'].forEach(function (id) { set(id, '–'); });
    ['ebBestNote', 'ebBuyNote', 'ebLeaseNote'].forEach(function (id) { set(id, ''); });
    clearBody('ebTable');
  }

  function update() {
    var method = document.getElementById('ebMethod').value;
    document.getElementById('ebLifeWrap').hidden = method !== 'sl';
    document.getElementById('ebRateWrap').hidden = method === 'sl';
    var v = {
      price: num('ebPrice'), salesTax: num('ebSalesTax'), down: num('ebDown'), buyFees: num('ebBuyFees'),
      loanRate: num('ebLoanRate'), loanTerm: Math.round(num('ebLoanTerm')), life: num('ebLife'), depRate: num('ebDepRate'),
      residual: num('ebResidual'), leasePay: num('ebLeasePay'), leaseTerm: Math.round(num('ebLeaseTerm')),
      deposit: num('ebDeposit'), leaseFees: num('ebLeaseFees'), tax: num('ebTaxRate')
    };
    ['salesTax', 'down', 'buyFees', 'deposit', 'leaseFees'].forEach(function (k) {
      var id = { salesTax: 'ebSalesTax', down: 'ebDown', buyFees: 'ebBuyFees', deposit: 'ebDeposit', leaseFees: 'ebLeaseFees' }[k];
      if (document.getElementById(id).value.trim() === '') v[k] = 0;
    });
    var discRaw = document.getElementById('ebDiscount').value.trim();
    var disc = discRaw === '' ? NaN : parseFloat(discRaw);
    var error = document.getElementById('ebError'), problem = '';
    function bad(x, lo, hi) { return isNaN(x) || x < lo || x > hi; }
    if (bad(v.price, 0.01, 1e10)) problem = 'Enter an equipment price above $0.';
    else if (bad(v.salesTax, 0, 30)) problem = 'Enter a sales tax rate from 0 to 30%.';
    else if (bad(v.down, 0, 1e10) || v.down > v.price * (1 + v.salesTax / 100) + 0.005) problem = 'Enter a down payment from $0 up to the price plus sales tax.';
    else if (bad(v.buyFees, 0, 1e10) || bad(v.deposit, 0, 1e10) || bad(v.leaseFees, 0, 1e10)) problem = 'Fees and the security deposit must be $0 or more.';
    else if (bad(v.loanRate, 0, 50)) problem = 'Enter a loan rate from 0 to 50%.';
    else if (bad(v.loanTerm, 1, 360)) problem = 'Enter a loan term from 1 to 360 months.';
    else if (method === 'sl' && bad(v.life, 1, 40)) problem = 'Enter a depreciation period from 1 to 40 years.';
    else if (method !== 'sl' && bad(v.depRate, 0, 100)) problem = 'Enter an annual depreciation rate from 0 to 100%.';
    else if (bad(v.residual, 0, 100)) problem = 'Enter an end-of-term value from 0 to 100% of the price.';
    else if (bad(v.leasePay, 0, 1e9)) problem = 'Enter a monthly lease payment of $0 or more.';
    else if (bad(v.leaseTerm, 1, 120)) problem = 'Enter a lease term from 1 to 120 months.';
    else if (bad(v.tax, 0, 60)) problem = 'Enter a tax rate from 0 to 60%.';
    else if (discRaw !== '' && bad(disc, 0, 50)) problem = 'Enter a discount rate from 0 to 50%, or leave it blank.';
    error.hidden = !problem;
    error.textContent = problem;
    if (problem) { clearResults(); return; }

    var tax = v.tax / 100;
    var discount = discRaw === '' ? v.loanRate / 100 * (1 - tax) : disc / 100;
    var r = analyse({
      price: v.price, salesTax: v.salesTax / 100, down: v.down, buyFees: v.buyFees, loanRate: v.loanRate / 100,
      loanTerm: v.loanTerm, method: method, life: v.life, depRate: v.depRate / 100, residual: v.residual / 100,
      leasePay: v.leasePay, leaseTerm: v.leaseTerm, deposit: v.deposit, leaseFees: v.leaseFees,
      advance: document.getElementById('ebAdvance').checked, tax: tax, disc: discount
    });

    var diff = r.leaseCost - r.buyCost;
    if (Math.abs(diff) < 0.5) {
      set('ebBestLabel', 'Better option'); set('ebBest', 'About even');
      set('ebBestNote', 'Both cost the same in today’s dollars.');
    } else {
      set('ebBestLabel', diff > 0 ? 'Buying saves' : 'Leasing saves');
      set('ebBest', fmt(Math.abs(diff)));
      set('ebBestNote', (diff > 0 ? 'Buy' : 'Lease') + ' costs less after tax, in today’s dollars.');
    }
    set('ebBuyNpv', fmt(r.buyCost));
    set('ebBuyNote', 'After the equipment’s ' + fmt(r.resale) + ' resale value.');
    set('ebLeaseNpv', fmt(r.leaseCost));
    set('ebLeaseNote', v.leaseTerm + ' payments of ' + money2.format(v.leasePay) + '.');
    set('ebLoanPay', r.loan > 0 ? money2.format(r.payment) : 'No loan');
    set('ebLoanAmt', fmt(r.loan));
    set('ebLoanLeft', fmt(r.loanLeft));
    set('ebBuyTax', fmt(r.buyTax) + (Math.abs(r.gainTax) >= 0.5 ? (r.gainTax > 0 ? ', less ' + fmt(r.gainTax) + ' tax on the resale gain' : ', plus ' + fmt(-r.gainTax) + ' on the resale loss') : ''));
    set('ebLeaseTax', fmt(r.leaseTax));
    set('ebRateUsed', (Math.round(discount * 10000) / 100).toFixed(2) + '%' + (discRaw === '' ? ' (after-tax loan rate)' : ''));

    var tb = clearBody('ebTable');
    r.years.forEach(function (y, idx) {
      addRow(tb, [String(idx), signed(y.bPay), signed(y.bTax), signed(y.bEnd), signed(y.bPay + y.bTax + y.bEnd),
                  signed(y.lPay + y.lEnd), signed(y.lTax), signed(y.lPay + y.lTax + y.lEnd)]);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('ebForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
